/bin/zsh -lc "python3 -B -c 'from itertools import combinations
edges = [(1, 2, 1), (2, 3, 2), (1, 3, 8)]
feasible = []
for k in range(len(edges) + 1):
    for subset in combinations(edges, k):
        reached = {1}
        while True:
            expanded = reached | {v for u,v,w in subset if u in reached} | {u for u,v,w in subset if v in reached}
            if expanded == reached:
                break
            reached = expanded
        if len(reached) == 3:
            feasible.append(sum(w for u,v,w in subset))
print({\"connected_subset_weights\": sorted(feasible), \"minimum\": min(feasible), \"expected_sample_output\": 3})
print({\"maximum_tree_weight_upper_bound\": (10**5 - 1) * 10**6})'"

